let time = 0;
let duration = 1000;
let runs = 0;
let fps = 60;
let figureRadius = 70;
let leftColor = "#28B78D";
let rightColor = "#243743";
let left = 0, right = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  rectMode(CENTER);
  ellipseMode(RADIUS);
  frameRate(60);
  noStroke();
  left = getFigure();
  runs++;
  right = getFigure();
}

function draw() {
  let bass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof bass_ratio !== 'undefined' ? bass_ratio : 0);
  let perc = (typeof percussive !== 'undefined') ? percussive : 0;

  let p = time / duration;
  let even = runs % 2 === 0;

  background(rightColor);

  push();
  translate(width / 2, height / 2);
  rotate(HALF_PI * p + (runs % 4 === 0 ? 0 : runs % 4 === 1 ? HALF_PI : runs % 4 === 2 ? PI : 3 * HALF_PI));

  let x = (even ? 1 : -1) * width / 3 * sin(PI * p);
  let angle = TWO_PI * p;

  fill(leftColor);
  rect(x - width / 2, 0, width, height * 2);
  fill(rightColor);
  rect(x + width / 2, 0, width, height * 2);

  let curRadius = figureRadius * (1.0 + bass * 0.4);

  fill(leftColor);
  if (x < 0) {
    if (!even) right = getFigure();
    push();
    translate(-x, 0);
    rotate(angle);
    drawFigure(left, p, curRadius);
    pop();

    push();
    translate(x, 0);
    drawWave(p, 1, curRadius);
    drawDrops(p, 1, curRadius);
    pop();
  }

  fill(rightColor);
  if (x > 0) {
    if (even) left = getFigure();
    push();
    translate(-x, 0);
    rotate(angle);
    drawFigure(right, p, curRadius);
    pop();

    push();
    translate(x, 0);
    drawWave(p, -1, curRadius);
    drawDrops(p, -1, curRadius);
    pop();
  }
  pop();

  time += 1000 / fps;
  if (time >= duration) {
    time -= duration;
    runs++;
  }
}

function getFigure() { return runs % 4; }

function drawFigure(figure, p, radius) {
  let t = 2 * (p <= 0.5 ? p : 1 - p);
  let r = radius * 0.5 * (1 + t);
  switch (figure) {
    case 0: drawCircle(t, r); break;
    case 1: drawSquare(t, r); break;
    case 2: drawTriangle(t, r); break;
    case 3: drawHeart(t, r); break;
  }
}

function drawCircle(p, radius) {
  ellipse(0, 0, radius, radius);
}

function drawTriangle(t, radius) {
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.05) {
    let r = cos(PI / 3) / cos(angle % (TWO_PI / 3) - PI / 3);
    let x = radius * cos(angle) * (1 + t * (r - 1));
    let y = radius * sin(angle) * (1 + t * (r - 1));
    vertex(x, y);
  }
  endShape(CLOSE);
}

function drawSquare(t, radius) {
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.05) {
    let r = 1 / cos(((angle + QUARTER_PI) % (HALF_PI) - QUARTER_PI));
    let x = radius * cos(angle) * (1 + t * (r - 1));
    let y = radius * sin(angle) * (1 + t * (r - 1));
    vertex(x, y);
  }
  endShape(CLOSE);
}

function drawHeart(t, radius) {
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.05) {
    let circleX = cos(angle - PI / 2);
    let circleY = sin(angle - PI / 2);
    let heartX = pow(sin(angle), 3);
    let heartY = (-13 * cos(angle) + 5 * cos(2 * angle) + 2 * cos(3 * angle) + cos(4 * angle)) / 17;
    vertex(radius * lerp(circleX, heartX, t), radius * lerp(circleY, heartY, t));
  }
  endShape(CLOSE);
}

function drawWave(p, dir, radius) {
  beginShape();
  for (let a = -PI / 2; a < 3 * PI / 2; a += radians(4)) {
    let wx = dir * radius * 0.5 * (sin((p > 0.5 ? 0.5 : p) * TWO_PI) * (sin(a) + 1)) - dir;
    let wy = map(a, 0, PI, -radius, radius);
    vertex(wx, wy);
  }
  endShape();
}

function drawDrops(p, dir, radius) {
  for (let i = 0; i < 10; i++) {
    let a = map(i, 0, 10, -HALF_PI, HALF_PI) + (dir === -1 ? PI : 0);
    let r = lerp(0, 5 * radius, p);
    let k = 2 * (1 - p);

    push();
    translate(r * cos(a), r * sin(a));
    rotate(a - HALF_PI);
    for (let j = 1; j < 6; j++) {
      ellipse(0, j * 2 * k, j * k, j * k);
    }
    pop();
  }
}
